#!/usr/bin/env python3
"""
tool.py - Monitor a file for checksum changes and notify a Discord webhook.
"""

import argparse
import hashlib
import logging
import os
import sys
import requests

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s [%(levelname)s] %(message)s",
    datefmt="%H:%M:%S",
)
logger = logging.getLogger("tool")


def compute_hash(filepath: str) -> str:
    """Compute SHA-256 hash of a local file in chunks."""
    hasher = hashlib.sha256()
    with open(filepath, "rb") as f:
        for chunk in iter(lambda: f.read(65536), b""):
            hasher.update(chunk)
    return hasher.hexdigest()


def load_previous_hash(state_file: str) -> str:
    """Read cached hash if state file exists."""
    if not os.path.exists(state_file):
        return ""
    try:
        with open(state_file, "r", encoding="ascii") as f:
            return f.read().strip()
    except OSError as err:
        logger.warning("Could not read state file: %s", err)
        return ""


def save_current_hash(state_file: str, digest: str) -> None:
    """Persist the newest hash to the state cache."""
    with open(state_file, "w", encoding="ascii") as f:
        f.write(digest)


def send_notification(webhook_url: str, filename: str, digest: str) -> bool:
    """Deliver a Discord message using standard incoming webhooks."""
    payload = {
        "content": f":bell: **File Update Detected**: `{filename}`\nSHA-256: `{digest[:12]}...`"
    }
    try:
        res = requests.post(webhook_url, json=payload, timeout=10)
        res.raise_for_status()
        return True
    except requests.RequestException as err:
        logger.error("Failed to send webhook: %s", err)
        return False


def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser(
        description="Track file changes by checksum and trigger Discord webhooks."
    )
    parser.add_argument(
        "--target",
        required=True,
        help="Path to the file to monitor",
    )
    parser.add_argument(
        "--webhook",
        required=True,
        help="Discord incoming webhook URL",
    )
    parser.add_argument(
        "--state",
        default=".tool_state.hash",
        help="Path to store previous hash (default: .tool_state.hash)",
    )
    parser.add_argument(
        "--dry-run",
        action="store_true",
        help="Check hash without notifying or updating state file",
    )
    return parser.parse_args()


def main() -> None:
    args = parse_args()

    if not os.path.exists(args.target):
        logger.error("Target file not found: %s", args.target)
        sys.exit(1)

    current_hash = compute_hash(args.target)
    logger.info("File: %s | SHA-256: %s", args.target, current_hash[:12])

    previous_hash = load_previous_hash(args.state)

    if not previous_hash:
        logger.info("Initial baseline recorded. Storing hash.")
        if not args.dry_run:
            save_current_hash(args.state, current_hash)
        return

    if current_hash == previous_hash:
        logger.info("No change detected.")
        return

    logger.warning("Hash mismatch! File content has changed.")
    if args.dry_run:
        logger.info("[DRY RUN] Would send Discord alert for %s", args.target)
        return

    success = send_notification(args.webhook, os.path.basename(args.target), current_hash)
    if success:
        save_current_hash(args.state, current_hash)
        logger.info("State updated successfully.")
    else:
        logger.error("Alert failed. State file unchanged for retry.")
        sys.exit(2)


if __name__ == "__main__":
    main()
